[
  {
    "operation": "shift",
    "spec": {
      "data": {
        "ratings": {
          "*": {
            // Định danh và thời gian
            "itemid": "reviews[&1].itemid",
            "shopid": "reviews[&1].shopid",
            "userid": "reviews[&1].userid",
            "cmtid": "reviews[&1].cmtid",
            "ctime": "reviews[&1].create_time_unix",
            "submit_time": "reviews[&1].submit_time_unix",
            // Nội dung và xếp hạng
            "comment": "reviews[&1].comment",
            "rating_star": "reviews[&1].rating_star",
            // Thông tin chi tiết điểm số (Detailed Rating)
            "detailed_rating": {
              "product_quality": "reviews[&2].score_product",
              "seller_service": "reviews[&2].score_seller",
              "delivery_service": "reviews[&2].score_delivery",
              "driver_service": "reviews[&2].score_driver"
            },
            // Người dùng và sản phẩm đã mua
            "author_username": "reviews[&1].author_username",
            "anonymous": "reviews[&1].is_anonymous",
            "is_repeated_purchase": "reviews[&1].is_repeated_purchase",
            // Phản hồi từ shop
            "ItemRatingReply": {
              "comment": "reviews[&1].shop_reply",
              "ctime": "reviews[&1].shop_reply_time"
            },
            // Các tag gợi ý (Độ êm, Chống thấm...)
            "template_tags": "reviews[&1].tags"
          }
        }
      }
    }
  },
  {
    // Bước này để làm phẳng mảng reviews ra root để dễ xử lý tiếp
    "operation": "shift",
